ltest = [{"n":i+1,"question_zh":f"（听录音，选一个）{a[0]} {a[1]} {a[2]}","script_zh":a[4],"options":["A","B","C"],"optionTexts":[a[0][2:],a[1][2:],a[2][2:]],"answer":a[3],"explanation_mn":a[5]} for i,a in enumerate(LISTEN_SCRIPT)]

def _mk(n,q,opts,ans,expl,seed,extra=None):
    o,_=shuffle(opts,ans,seed); d={"n":n,"question_zh":q,"options":o,"answer":ans,"explanation_mn":expl}
    if extra: d.update(extra)
    return d
def FT(n,q,py,ans,dis,expl,seed): return _mk(n,q,[ans]+dis,ans,expl,seed,{"pinyin_hint":py})
def SI(n,q,ans,expl,seed): return _mk(n,q,["1","2","3","4","5"],ans,expl,seed)
def RD(n,imgname,A,B,C,ans,expl,seed):
    opts={"A":"A "+A,"B":"B "+B,"C":"C "+C}
    return _mk(n,f"（看图，选句子）",[opts["A"],opts["B"],opts["C"]],opts[ans],expl,seed,{"image":img(imgname)})
WR=["牙疼","高兴","吃饺子","做作业"]
def WS(n,q,ans,expl,seed): return _mk(n,q,["A 牙疼","B 高兴","C 吃饺子","D 做作业"],ans,expl,seed)
